package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class FirstReleaseVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property first release of observed issue ")
  void test_first_release_v_o_builder() {
    Assertions.assertFalse(FirstReleaseVO.nullValue().getFirstRelease().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(FirstReleaseVO.tryFrom(null).getFirstRelease().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", FirstReleaseVO.from("one").getFirstRelease().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> FirstReleaseVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", FirstReleaseVO.from("one").toString());
  }
}
